node -e "
const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
console.log('File size:', buf.length);
console.log('Header:', buf.slice(0, 20).toString('utf8'));
"

npm install better-sqlite3 2>/dev/null 1>/dev/null && node -e "
const db = require('better-sqlite3')('/workspace/world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables.map(t => t.name));
"

node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Search orders for W4407627
const order = db.prepare(\"SELECT * FROM orders WHERE order_id LIKE '%W4407627%' OR order_id = 'W4407627'\").all();
console.log('=== Orders matching W4407627 ===');
console.log(JSON.stringify(order, null, 2));

// Search order_items
const items = db.prepare(\"SELECT * FROM order_items WHERE order_id LIKE '%W4407627%' OR order_id = 'W4407627'\").all();
console.log('\n=== Order Items matching W4407627 ===');
console.log(JSON.stringify(items, null, 2));
"
